import java.util.*;
import java.io.*;

public class Div680 {
    private static int capacity, prime, shift;
    private static int[][][] cache;

    public static void main(String[] args) throws Exception {
        BufferedReader console = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = console.readLine().split(" ");
        capacity = Integer.parseInt(tokens[0]);
        prime = Integer.parseInt(tokens[1]);
        shift = capacity * (capacity - 1);
        cache = new int[2][capacity][2 * shift + 1];
        for (int[][] block : cache) {
            for (int[] row : block) Arrays.fill(row, -1);
        }
        System.out.println(process(0));
        console.close();
    }

    private static long process(int position) {
        if (position == capacity - 1) return 0;
        long accumulator = ((long)(capacity - position) * process(position + 1)) % prime;
        for (int left = 0; left < capacity - position; left++) {
            for (int right = left + 1; right < capacity - position; right++) {
                accumulator = (accumulator + evaluate(1, position + 1, left - right)) % prime;
            }
        }
        return accumulator;
    }

    private static int evaluate(int state, int depth, int balance) {
        if (depth == capacity) return balance > 0 ? 1 : 0;
        int lookup = balance + shift;
        if (cache[state][depth][lookup] != -1) return cache[state][depth][lookup];
        int free = capacity - depth;
        long result = 0;
        for (int i = 0; i < free; i++) {
            int jMin = (state == 1) ? 0 : i;
            for (int j = jMin; j < free; j++) {
                int newState = state | ((i < j) ? 1 : 0);
                result = (result + evaluate(newState, depth + 1, balance + i - j)) % prime;
            }
        }
        return cache[state][depth][lookup] = (int)result;
    }

    private static long gcd(long first, long second) {
        return first == 0 ? second : gcd(second % first, first);
    }

    static class InputScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        InputScanner(InputStream stream) { reader = new BufferedReader(new InputStreamReader(stream)); }
        InputScanner(FileReader fr) { reader = new BufferedReader(fr); }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) tokenizer = new StringTokenizer(reader.readLine());
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        String nextLine() throws IOException { return reader.readLine(); }

        double nextDouble() throws IOException {
            String raw = next();
            boolean sign = raw.charAt(0) == '-';
            if (sign) raw = raw.substring(1);
            double total = 0;
            double divisor = 1;
            boolean point = false;
            for (int i = 0; i < raw.length(); i++) {
                char c = raw.charAt(i);
                if (c == '.') { point = true; continue; }
                total = total * 10 + (c - '0');
                if (point) divisor *= 10;
            }
            return (total / divisor) * (sign ? -1 : 1);
        }

        boolean ready() throws IOException { return reader.ready(); }
    }
}
